/*
 * Tests for the evaluator part registry and its dispatch
 * (src/evaluator_machine_internal.h, generated by cmake/SxmlParts.cmake;
 * D101).
 *
 * Golden file: tests/memory_test.c (fixture, allocation-failure loops),
 * with the hand-built IR of tests/ir_test.c and the evaluation of
 * tests/evaluator_test.c. Every IR kind reserved for XQuery and XSLT must
 * be claimed by exactly one part and no XPath kind by any; until Phases 3
 * and 4 fill the parts, evaluating a reserved kind or a global variable
 * with an initializer is SXML_STATUS_UNSUPPORTED_FEATURE and releases
 * everything. Kinds whose part is filled (evaluated_kinds) are tested in
 * their part's own test (TRY_CATCH: tests/evaluator_try_test.c).
 */
#include "evaluator_machine_internal.h"
#include "ir_internal.h"
#include "sxml/name.h"
#include "sxml/types.h"
#include "sxml/xdm.h"
#include "test_runner.h"

#include <stdalign.h>
#include <string.h>

/* The kinds an evaluator part evaluates (src/ir_internal.h, D55). */
static const sxml_ir_expression_kind reserved_kinds[] = {
    SXML_IR_EXPRESSION_KIND_TRY_CATCH,
    SXML_IR_EXPRESSION_KIND_DOCUMENT_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_ELEMENT_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_ATTRIBUTE_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_NAMESPACE_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_TEXT_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_COMMENT_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_PROCESSING_INSTRUCTION_CONSTRUCTOR,
    SXML_IR_EXPRESSION_KIND_SHALLOW_COPY,
    SXML_IR_EXPRESSION_KIND_APPLY_TEMPLATES,
};

/* The reserved kinds whose part is filled: TRY_CATCH (packet 3.6). */
static const sxml_ir_expression_kind evaluated_kinds[] = {
    SXML_IR_EXPRESSION_KIND_TRY_CATCH,
};

static bool is_evaluated_kind(sxml_ir_expression_kind kind) {
    for (size_t kind_index = 0; kind_index < SXML_TEST_COUNT(evaluated_kinds);
         kind_index += 1) {
        if (evaluated_kinds[kind_index] == kind) {
            return true;
        }
    }
    return false;
}

static bool is_reserved_kind(sxml_ir_expression_kind kind) {
    for (size_t kind_index = 0; kind_index < SXML_TEST_COUNT(reserved_kinds);
         kind_index += 1) {
        if (reserved_kinds[kind_index] == kind) {
            return true;
        }
    }
    return false;
}

static sxml_byte_view text_view(const char *text) {
    return (sxml_byte_view){.bytes = (const uint8_t *)text, .byte_count = strlen(text)};
}

/* ---------------------------------------------------------- Registry */

static void test_registry_lists_the_parts(sxml_test_state *state) {
    static const char *const part_names[] = {"construct", "global", "template", "try"};
    const sxml_evaluator_registered_part_view registered = sxml_evaluator_registered_parts();
    for (size_t name_index = 0; name_index < SXML_TEST_COUNT(part_names); name_index += 1) {
        bool is_found = false;
        for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
            const sxml_evaluator_registered_part *part = &registered.parts[part_index];
            is_found = is_found || (sxml_byte_view_equals(part->part_name,
                                                          text_view(part_names[name_index])) &&
                                    part->part != NULL);
        }
        SXML_TEST_EXPECT(state, is_found);
    }
    /* evaluator_function.c and evaluator_path.c define no part. */
    SXML_TEST_EXPECT(state, registered.part_count >= SXML_TEST_COUNT(part_names));
    for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
        const sxml_byte_view part_name = registered.parts[part_index].part_name;
        SXML_TEST_EXPECT(state, !sxml_byte_view_equals(part_name, text_view("function")) &&
                                    !sxml_byte_view_equals(part_name, text_view("path")));
    }
}

static void test_each_reserved_kind_has_one_part(sxml_test_state *state) {
    for (uint32_t kind_value = 0; kind_value < (uint32_t)SXML_IR_EXPRESSION_KIND_COUNT;
         kind_value += 1) {
        const sxml_ir_expression_kind kind = (sxml_ir_expression_kind)kind_value;
        const bool has_handler = sxml_evaluator_find_kind_handler(kind) != NULL;
        SXML_TEST_EXPECT(state, has_handler == is_reserved_kind(kind));
    }
}

/* ------------------------------------------------------------ Fixture */

typedef struct fixture {
    sxml_counting_allocator *counting_allocator;
    alignas(16) uint8_t counting_storage[256];
    sxml_name_pool *name_pool;
    sxml_type_registry *registry;
    sxml_item_heap *item_heap;
    sxml_dynamic_context *dynamic_context;
} fixture;

static sxml_allocator fixture_allocator(const fixture *test_fixture) {
    return sxml_counting_allocator_as_allocator(test_fixture->counting_allocator);
}

static sxml_status fixture_create(uint64_t failing_allocation_number,
                                  fixture *test_fixture) {
    *test_fixture = (fixture){.counting_allocator = NULL};
    sxml_status status = sxml_counting_allocator_initialize(
        (sxml_memory_view){.bytes = test_fixture->counting_storage,
                           .byte_count = sizeof(test_fixture->counting_storage)},
        &(sxml_counting_allocator_configuration){
            .backing_allocator = sxml_default_allocator(),
            .failing_allocation_number = failing_allocation_number},
        &test_fixture->counting_allocator);
    if (status == SXML_STATUS_OK) {
        status = sxml_name_pool_create(
            sxml_default_allocator(),
            &(sxml_name_pool_configuration){.allocator = sxml_default_allocator(),
                                            .maximum_byte_count = 0},
            &test_fixture->name_pool);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_type_registry_create(
            sxml_default_allocator(),
            &(sxml_type_registry_configuration){.allocator = sxml_default_allocator(),
                                                .name_pool = test_fixture->name_pool,
                                                .maximum_registered_type_count = 0},
            &test_fixture->registry);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_item_heap_create(
            fixture_allocator(test_fixture),
            &(sxml_item_heap_configuration){.allocator = fixture_allocator(test_fixture),
                                            .name_pool = test_fixture->name_pool,
                                            .type_registry = test_fixture->registry,
                                            .maximum_byte_count = 0},
            &test_fixture->item_heap);
    }
    if (status == SXML_STATUS_OK) {
        sxml_evaluator_configuration configuration;
        memset(&configuration, 0, sizeof(configuration));
        configuration.item_heap = test_fixture->item_heap;
        configuration.allocator = fixture_allocator(test_fixture);
        status = sxml_dynamic_context_create(fixture_allocator(test_fixture), &configuration,
                                             &test_fixture->dynamic_context);
    }
    return status;
}

/* Destroys the fixture; true when every block and cell was released. */
static bool fixture_destroy(fixture *test_fixture) {
    sxml_dynamic_context_destroy(test_fixture->dynamic_context);
    bool released = true;
    if (test_fixture->item_heap != NULL) {
        sxml_item_heap_clear_raised_error(test_fixture->item_heap);
        released = sxml_item_heap_read_counts(test_fixture->item_heap).live_cell_count == 0;
    }
    sxml_item_heap_destroy(test_fixture->item_heap);
    sxml_type_registry_destroy(test_fixture->registry);
    sxml_name_pool_destroy(test_fixture->name_pool);
    if (test_fixture->counting_allocator != NULL) {
        released = released &&
                   sxml_counting_allocator_read_counts(test_fixture->counting_allocator)
                           .live_allocation_count == 0;
        sxml_counting_allocator_finalize(test_fixture->counting_allocator);
    }
    *test_fixture = (fixture){.counting_allocator = NULL};
    return released;
}

/* ---------------------------------------------------------------- Units */

/* What the main function of a test unit holds. */
typedef struct unit_request {
    /* The kind of its body, every field zero. */
    sxml_ir_expression_kind body_kind;
    /* True for one global variable whose initializer is the main
       function. */
    bool has_initialized_global;
} unit_request;

/* Builds and seals a unit whose main function's body is an expression of
   request->body_kind. */
static sxml_status build_unit(const fixture *test_fixture, const unit_request *request,
                              sxml_ir_unit **unit) {
    sxml_status status = sxml_ir_unit_create(
        fixture_allocator(test_fixture),
        &(sxml_ir_unit_configuration){.allocator = fixture_allocator(test_fixture),
                                      .item_heap = test_fixture->item_heap,
                                      .source_name = text_view("machine"),
                                      .maximum_expression_count = 0},
        unit);
    if (status != SXML_STATUS_OK) {
        return status;
    }
    sxml_ir_function_index main_function = {0};
    sxml_ir_expression_index body = {0};
    status = sxml_ir_unit_add_function(*unit, &(sxml_ir_function){.slot_count = 0},
                                       &main_function);
    if (status == SXML_STATUS_OK) {
        sxml_ir_expression expression;
        memset(&expression, 0, sizeof(expression));
        expression.expression_kind = request->body_kind;
        status = sxml_ir_unit_add_expression(*unit, &expression, &body);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_ir_unit_replace_function(
            *unit, &(sxml_ir_function_replacement){
                       .index = main_function,
                       .function = {.slot_count = 0, .body = body}});
    }
    if (status == SXML_STATUS_OK && request->has_initialized_global) {
        sxml_ir_global_index global = {0};
        status = sxml_ir_unit_add_global_variable(
            *unit, &(sxml_ir_global_variable){.initializer = main_function}, &global);
    }
    if (status != SXML_STATUS_OK) {
        sxml_ir_unit_release(*unit);
        *unit = NULL;
        return status;
    }
    sxml_ir_unit_seal(*unit);
    return SXML_STATUS_OK;
}

/* Evaluates a unit built from request and writes its status. */
static sxml_status evaluate_unit(const fixture *test_fixture, const unit_request *request,
                                 sxml_status *evaluation_status) {
    sxml_ir_unit *unit = NULL;
    sxml_status status = build_unit(test_fixture, request, &unit);
    if (status != SXML_STATUS_OK) {
        return status;
    }
    const sxml_evaluator_slot absent_global = {.value = sxml_sequence_empty(),
                                               .slot_state = SXML_EVALUATOR_SLOT_STATE_ABSENT};
    sxml_error_record error_record;
    memset(&error_record, 0, sizeof(error_record));
    sxml_sequence value = sxml_sequence_empty();
    *evaluation_status = sxml_evaluator_evaluate(
        test_fixture->dynamic_context,
        &(sxml_evaluation_request){
            .unit = unit,
            .has_context_value = false,
            .context_value = sxml_sequence_empty(),
            .global_values = {.slots = &absent_global,
                              .slot_count = request->has_initialized_global ? 1 : 0},
            .static_base_uri = {.bytes = NULL, .byte_count = 0},
            .error_record = &error_record},
        &value);
    sxml_sequence_release(value);
    sxml_ir_unit_release(unit);
    return SXML_STATUS_OK;
}

static void test_reserved_kinds_are_unsupported(sxml_test_state *state) {
    for (size_t kind_index = 0; kind_index < SXML_TEST_COUNT(reserved_kinds);
         kind_index += 1) {
        if (is_evaluated_kind(reserved_kinds[kind_index])) {
            continue;
        }
        fixture test_fixture;
        SXML_TEST_REQUIRE(state, fixture_create(0, &test_fixture) == SXML_STATUS_OK);
        sxml_status evaluation_status = SXML_STATUS_OK;
        SXML_TEST_EXPECT(state, evaluate_unit(&test_fixture,
                                              &(unit_request){.body_kind =
                                                                  reserved_kinds[kind_index],
                                                              .has_initialized_global = false},
                                              &evaluation_status) == SXML_STATUS_OK);
        SXML_TEST_EXPECT(state, evaluation_status == SXML_STATUS_UNSUPPORTED_FEATURE);
        SXML_TEST_EXPECT(state, fixture_destroy(&test_fixture));
    }
}

static void test_initialized_global_is_unsupported(sxml_test_state *state) {
    fixture test_fixture;
    SXML_TEST_REQUIRE(state, fixture_create(0, &test_fixture) == SXML_STATUS_OK);
    sxml_status evaluation_status = SXML_STATUS_OK;
    /* The body alone evaluates (an empty atom: the empty sequence). */
    SXML_TEST_EXPECT(state, evaluate_unit(&test_fixture,
                                          &(unit_request){.body_kind =
                                                              SXML_IR_EXPRESSION_KIND_ATOM,
                                                          .has_initialized_global = false},
                                          &evaluation_status) == SXML_STATUS_OK);
    SXML_TEST_EXPECT(state, evaluation_status == SXML_STATUS_OK);
    SXML_TEST_EXPECT(state, evaluate_unit(&test_fixture,
                                          &(unit_request){.body_kind =
                                                              SXML_IR_EXPRESSION_KIND_ATOM,
                                                          .has_initialized_global = true},
                                          &evaluation_status) == SXML_STATUS_OK);
    SXML_TEST_EXPECT(state, evaluation_status == SXML_STATUS_UNSUPPORTED_FEATURE);
    SXML_TEST_EXPECT(state, fixture_destroy(&test_fixture));
}

static void test_dispatch_survives_every_allocation_failure(sxml_test_state *state) {
    bool succeeded = false;
    for (uint64_t failing_allocation_number = 1; !succeeded && failing_allocation_number < 1000;
         failing_allocation_number += 1) {
        fixture test_fixture;
        sxml_status status = fixture_create(failing_allocation_number, &test_fixture);
        sxml_status evaluation_status = SXML_STATUS_OK;
        if (status == SXML_STATUS_OK) {
            status = evaluate_unit(&test_fixture,
                                   &(unit_request){.body_kind = SXML_IR_EXPRESSION_KIND_APPLY_TEMPLATES,
                                                   .has_initialized_global = false},
                                   &evaluation_status);
        }
        if (status == SXML_STATUS_OK) {
            status = evaluation_status;
        }
        succeeded = status == SXML_STATUS_UNSUPPORTED_FEATURE;
        SXML_TEST_EXPECT(state, succeeded || status == SXML_STATUS_OUT_OF_MEMORY);
        SXML_TEST_EXPECT(state, fixture_destroy(&test_fixture));
    }
    SXML_TEST_EXPECT(state, succeeded);
}

static const sxml_test_case evaluator_machine_test_cases[] = {
    {.name = "registry_lists_the_parts", .function = test_registry_lists_the_parts},
    {.name = "each_reserved_kind_has_one_part",
     .function = test_each_reserved_kind_has_one_part},
    {.name = "reserved_kinds_are_unsupported", .function = test_reserved_kinds_are_unsupported},
    {.name = "initialized_global_is_unsupported",
     .function = test_initialized_global_is_unsupported},
    {.name = "dispatch_survives_every_allocation_failure",
     .function = test_dispatch_survives_every_allocation_failure},
};

int main(int argument_count, char **arguments) {
    return sxml_test_run_suite(
        &(sxml_test_suite){
            .name = "evaluator_machine",
            .cases = evaluator_machine_test_cases,
            .case_count = SXML_TEST_COUNT(evaluator_machine_test_cases),
        },
        (sxml_test_command_line){
            .argument_count = argument_count,
            .arguments = arguments,
        });
}
